"""Detecta en el HTML de una portada si hay selector de idioma y si incluye el valenciano.

Uso como script: python3 -I lang_detect.py <dir_html> <salida.json>
Lee <dir>/index.json (de fetch_pages.py) y analiza cada <n>.html.
"""
import json
import os
import re
import sys
from html.parser import HTMLParser

CLICKABLE = {"a", "button", "option", "li", "span", "div", "label"}
MAX_TEXT = 30
# Etiquetas de idioma tal y como aparecen en botones/enlaces
VAL_TEXT = re.compile(r"^(valenci[àa]|valenciano|val|va|vl|cat|ca|catal[àa]|catal[áa]n|"
                      r"versi[óo] en valenci[àa]|en valenci[àa]|valencian)$", re.I)
OTHER_TEXT = re.compile(r"^(castellano|espa[ñn]ol|castell[àa]|cas|es|esp|spanish|english|"
                        r"ingl[ée]s|angl[èe]s|en|eng|fran[çc]ais|fr|deutsch|de|"
                        r"versi[óo]n en castellano|en castellano)$", re.I)
VAL_CODE = re.compile(r"^(ca|va|val|vl|ca[-_](es|valencia|va)|ca[-_]es[-_]valencia|va[-_]es)$", re.I)
OTHER_CODE = re.compile(r"^(es|es[-_]es|en|en[-_](gb|us)|fr|fr[-_]fr|de|de[-_]de|it|ru|nl)$", re.I)
# Parámetros/rutas de cambio de idioma en href
VAL_HREF = re.compile(r"([?&](lang|idioma|language|locale|lng|hl|setlang|ln)=(ca|va|val|vl)\b)|"
                      r"(/(ca|va|val|vl|ca-es|ca-valencia|va-es|valencia|valencian)(/|$|\?))", re.I)
OTHER_HREF = re.compile(r"([?&](lang|idioma|language|locale|lng|hl|setlang|ln)=(es|en|cas)\b)|"
                        r"(/(es|en|es-es|cas|castellano)(/|$|\?))", re.I)
