                      r"(/(ca|va|val|vl|ca-es|ca-valencia|va-es|valencia|valencian)(/|$|\?))", re.I)
OTHER_HREF = re.compile(r"([?&](lang|idioma|language|locale|lng|hl|setlang|ln)=(es|en|cas)\b)|"
                        r"(/(es|en|es-es|cas|castellano)(/|$|\?))", re.I)
TRANSLATE_WIDGET = re.compile(r"translate\.google|google_translate_element|gtranslate|goog-te-", re.I)


class LangParser(HTMLParser):
    """Recoge elementos clicables con texto corto y atributos de idioma."""

    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.stack = []
        self.items = []
        self.hreflangs = []
        self.html_lang = ""

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag == "html":
            self.html_lang = (attrs.get("lang") or attrs.get("xml:lang") or "").strip()
        if tag == "link" and attrs.get("hreflang"):
            self.hreflangs.append(("link", attrs.get("hreflang"), attrs.get("href") or ""))
        if tag == "a" and attrs.get("hreflang"):
            self.hreflangs.append(("a", attrs.get("hreflang"), attrs.get("href") or ""))
        if tag == "img" and self.stack:
            # banderas: el texto del enlace es el alt/title de la imagen
            self.stack[-1]["text"] += " " + (attrs.get("alt") or attrs.get("title") or "")
        if tag in CLICKABLE:
            self.stack.append({"tag": tag, "attrs": attrs, "text": ""})

    def handle_endtag(self, tag):
        for pos in range(len(self.stack) - 1, -1, -1):
            if self.stack[pos]["tag"] == tag:
                elem = self.stack.pop(pos)
                text = re.sub(r"\s+", " ", elem["text"]).strip()
                if pos > 0:
                    self.stack[pos - 1]["text"] += " " + elem["text"]
                if 0 < len(text) <= MAX_TEXT or elem["attrs"].get("lang"):
                    self.items.append({"tag": tag, "text": text, "attrs": elem["attrs"]})
                return

    def handle_data(self, data):
        if self.stack:
            self.stack[-1]["text"] += data


def attr_text(attrs):
    keys = ("title", "aria-label", "alt", "data-lang", "lang", "value", "data-language")
    return [str(attrs.get(k) or "").strip() for k in keys if attrs.get(k)]


def analyse(body):
    parser = LangParser()
    try:
        parser.feed(body)
    except Exception as exc:  # HTML muy roto: se informa y se sigue
        return {"error": str(exc)}
    val_ev, other_ev = [], []
    for item in parser.items:
        text, attrs = item["text"], item["attrs"]
        href = str(attrs.get("href") or attrs.get("value") or "")
        labels = [text] + attr_text(attrs)
        is_link = item["tag"] in ("a", "button", "option") or attrs.get("onclick") or attrs.get("href")
        if not is_link:
            continue
        for label in labels:
            short = label.strip(" |·-[]()").strip()
            if VAL_TEXT.match(short) or re.search(r"valenci[àa]|valenciano", short, re.I) and len(short) <= MAX_TEXT:
                val_ev.append(f"{item['tag']}:{short}|{href[:80]}")
            elif OTHER_TEXT.match(short):
                other_ev.append(f"{item['tag']}:{short}|{href[:80]}")
        if len(text) <= 4 and VAL_HREF.search(href):
            val_ev.append(f"{item['tag']}@href:{text}|{href[:80]}")
        elif len(text) <= 4 and OTHER_HREF.search(href):
            other_ev.append(f"{item['tag']}@href:{text}|{href[:80]}")
        lang_attr = str(attrs.get("lang") or attrs.get("hreflang") or "")
        if VAL_CODE.match(lang_attr):
            val_ev.append(f"{item['tag']}@lang={lang_attr}|{href[:80]}")
        elif OTHER_CODE.match(lang_attr):
            other_ev.append(f"{item['tag']}@lang={lang_attr}|{href[:80]}")
    for kind, code, href in parser.hreflangs:
        target = val_ev if VAL_CODE.match(code) else other_ev if OTHER_CODE.match(code) else None
        if target is not None:
            target.append(f"{kind}@hreflang={code}|{href[:80]}")
    return {"html_lang": parser.html_lang, "val_ev": sorted(set(val_ev))[:12],
            "other_ev": sorted(set(other_ev))[:12],
            "translate_widget": bool(TRANSLATE_WIDGET.search(body))}


def main(html_dir, dst):
    index = json.load(open(os.path.join(html_dir, "index.json"), encoding="utf-8"))
    out = []
    for entry in index:
        with open(os.path.join(html_dir, f"{entry['idx']}.html"), encoding="utf-8") as fh:
            body = fh.read()
        out.append({**entry, **analyse(body)})
    with open(dst, "w", encoding="utf-8") as fh:
        json.dump(out, fh, ensure_ascii=False, indent=1)
    has_val = sum(1 for o in out if o.get("val_ev"))
    only_other = sum(1 for o in out if not o.get("val_ev") and o.get("other_ev"))
    print(f"total={len(out)} con_val={has_val} solo_otros={only_other} "
          f"sin_selector={len(out) - has_val - only_other}")


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])

