import json
import os
import re
import sys
from html.parser import HTMLParser

CLICKABLE = {"a", "button", "option", "li", "span", "div", "label"}
LINK_TAGS = {"a", "button", "option"}
MAX_TEXT = 40
WORD = re.compile(r"[a-zà-ÿ·]+", re.I)
VAL_WORDS = {"valencià", "valenciano", "valencian", "va", "val", "vl", "ca", "cat", "català",
             "catalán", "catalan"}
OTHER_WORDS = {"castellano", "español", "espanol", "castellà", "cas", "es", "esp", "spanish",
               "english", "inglés", "ingles", "anglès", "en", "eng", "français", "francés", "fr",
               "deutsch", "alemán", "de", "italiano", "it", "русский", "nederlands"}
FILLER = {"cambiar", "canviar", "canvia", "cambia", "switch", "to", "a", "al", "en", "ver", "veure",
          "versió", "versión", "idioma", "language", "lengua", "llengua", "el", "la", "in", "selecciona",
          "seleccionar", "logo", "bandera", "flag", "icon", "icono"}
VAL_CODE = re.compile(r"^(ca|va|val|vl|ca[-_](es|valencia|va)|ca[-_]es[-_]valencia|va[-_]es)$", re.I)
OTHER_CODE = re.compile(r"^(es|es[-_]es|en|en[-_](gb|us)|fr|fr[-_]fr|de|de[-_]de|it|ru|nl)$", re.I)
