VAL_HREF = re.compile(r"([?&](lang|idioma|language|locale|lng|hl|setlang|ln)=(ca|va|val|vl)\b)|"
                      r"(/(ca|va|val|vl|ca-es|ca-valencia|va-es)/?(\?|$))", re.I)
OTHER_HREF = re.compile(r"([?&](lang|idioma|language|locale|lng|hl|setlang|ln)=(es|en|cas)\b)|"
                        r"(/(es|en|es-es|cas)/?(\?|$))", re.I)
