"""Detecta en el HTML de una portada si hay selector de idioma y si incluye el valenciano.

Uso como script: python3 -I lang_detect.py <dir_html> <salida.json>
Lee <dir>/index.json (de fetch_pages.py) y analiza cada <n>.html.
"""
import json
import os
import re
import sys
from html.parser import HTMLParser
from urllib.parse import urlparse

CLICKABLE = {"a", "button", "option", "li", "span", "div", "label"}
LINK_TAGS = {"a", "button", "option"}
MAX_TEXT = 40
MAX_LANG_PATH = 12  # enlaces-bandera apuntan a "/", "/va/", "/es/index.aspx"..., no a noticias
WORD = re.compile(r"[a-zà-ÿ·]+", re.I)
VAL_WORDS = {"valencià", "valenciano", "valencian", "va", "val", "vl", "ca", "cat", "català",
             "catalán", "catalan", "valenciana"}
OTHER_WORDS = {"castellano", "español", "espanol", "castellà", "cas", "es", "esp", "spanish",
               "english", "inglés", "ingles", "anglès", "en", "eng", "français", "francés", "fr",
               "deutsch", "alemán", "de", "italiano", "it", "русский", "nederlands"}
FILLER = {"cambiar", "canviar", "canvia", "cambia", "switch", "to", "a", "al", "en", "ver", "veure",
          "versió", "versión", "idioma", "language", "lengua", "llengua", "el", "la", "in", "selecciona",
          "seleccionar", "logo", "bandera", "flag", "icon", "icono"}
VAL_CODE = re.compile(r"^(ca|va|val|vl|ca[-_](es|valencia|va)|ca[-_]es[-_]valencia|va[-_]es)$", re.I)
OTHER_CODE = re.compile(r"^(es|es[-_]es|en|en[-_](gb|us)|fr|fr[-_]fr|de|de[-_]de|it|ru|nl)$", re.I)
# Parámetros/rutas de cambio de idioma en href (solo se usan si el enlace no tiene texto: banderas)
VAL_HREF = re.compile(r"([?&](lang|idioma|language|locale|lng|hl|setlang|ln)=(ca|va|val|vl)\b)|"
                      r"(/(ca|va|val|vl|ca-es|ca-valencia|va-es)/?(\?|$))", re.I)
OTHER_HREF = re.compile(r"([?&](lang|idioma|language|locale|lng|hl|setlang|ln)=(es|en|cas)\b)|"
                        r"(/(es|en|es-es|cas)/?(\?|$))", re.I)
TRANSLATE_WIDGET = re.compile(r"translate\.google|google_translate_element|gtranslate|goog-te-", re.I)


class LangParser(HTMLParser):
    """Recoge elementos clicables con texto corto y atributos de idioma."""

    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.stack = []
        self.items = []
        self.hreflangs = []
        self.html_lang = ""

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag == "html":
            self.html_lang = (attrs.get("lang") or attrs.get("xml:lang") or "").strip()
        if tag == "link" and attrs.get("hreflang"):
            self.hreflangs.append((attrs.get("hreflang"), attrs.get("href") or ""))
        if tag == "img" and self.stack:
            # banderas: el texto del enlace es el alt/title de la imagen
            self.stack[-1]["text"] += " " + (attrs.get("alt") or attrs.get("title") or "")
        if tag in CLICKABLE:
            self.stack.append({"tag": tag, "attrs": attrs, "text": ""})

    def handle_endtag(self, tag):
        for pos in range(len(self.stack) - 1, -1, -1):
            if self.stack[pos]["tag"] == tag:
                elem = self.stack.pop(pos)
                if pos > 0:
                    self.stack[pos - 1]["text"] += " " + elem["text"]
                text = re.sub(r"\s+", " ", elem["text"]).strip()
                if len(text) <= MAX_TEXT:
                    self.items.append({"tag": tag, "text": text, "attrs": elem["attrs"]})
                return

    def handle_data(self, data):
        if self.stack:
            self.stack[-1]["text"] += data


def label_kind(label):
    """'val', 'other' o None según si la etiqueta es un nombre/código de idioma."""
    words = [w.lower() for w in WORD.findall(label)]
    if not words or len(words) > 5:
        return None
    if all(w in VAL_WORDS | FILLER for w in words) and any(w in VAL_WORDS for w in words):
        return "val"
    if all(w in OTHER_WORDS | FILLER for w in words) and any(w in OTHER_WORDS for w in words):
        return "other"
    return None


def same_site(href, host):
    target = urlparse(href).hostname
    return not target or target.removeprefix("www.") == host


def classify_item(item, host):
    """Devuelve lista de (tipo, evidencia) para un elemento clicable."""
    tag, text, attrs = item["tag"], item["text"], item["attrs"]
    href = str(attrs.get("href") or attrs.get("value") or "")
    is_link = tag in LINK_TAGS or attrs.get("onclick") or attrs.get("href")
    labels = [text] + [str(attrs.get(k)) for k in ("title", "aria-label", "data-lang") if attrs.get(k)]
    found = []
    if not same_site(href, host):  # un selector de idioma nunca enlaza a otra web
        return found
    for label in labels:
        kind = label_kind(label)
        if kind:
            found.append((kind if is_link else f"{kind}_nolink", f"{tag}:{label.strip()[:30]}|{href[:70]}"))
    # hreflang/lang en enlaces de contenido (titulares) no es un selector: solo enlaces sin texto
    code = str(attrs.get("hreflang") or attrs.get("lang") or "")
    if is_link and not WORD.search(text) and len(urlparse(href).path) <= MAX_LANG_PATH:
        if VAL_CODE.match(code):
            found.append(("val", f"{tag}@lang={code}:{text}|{href[:70]}"))
        elif OTHER_CODE.match(code):
            found.append(("other", f"{tag}@lang={code}:{text}|{href[:70]}"))
    if tag == "a" and not WORD.search(text):
        if VAL_HREF.search(href):
            found.append(("val", f"a@href|{href[:70]}"))
        elif OTHER_HREF.search(href):
            found.append(("other", f"a@href|{href[:70]}"))
    return found


def decide(evidence, html_lang):
    """true: hay opción de valenciano; false: hay selector sin valenciano; null: no hay selector."""
    if evidence["val"]:
        labels = [ev.split("|")[0] for ev in evidence["val"]]
        if all(re.search(r"catal", label, re.I) for label in labels):
            return "true", "botón etiquetado como Català/Catalan"
        return "true", "botón de valenciano"
    if evidence["other"]:
        if evidence["val_nolink"] or VAL_CODE.match(html_lang.split("-")[0] or "-"):
            return "true", "valenciano es el idioma activo; el selector ofrece otros"
        return "false", "selector de idioma sin valenciano"
    return "null", "no se encuentra selector de idioma"


def analyse(body, page_url):
    parser = LangParser()
    try:
        parser.feed(body)
    except Exception as exc:  # HTML muy roto: se informa y se sigue
        return {"error": str(exc)}
    host = (urlparse(page_url).hostname or "").removeprefix("www.")
    evidence = {"val": set(), "other": set(), "val_nolink": set(), "other_nolink": set()}
    for item in parser.items:
        for kind, ev in classify_item(item, host):
            evidence[kind].add(ev)
    alternates = sorted({code for code, _ in parser.hreflangs})
    valenciano, motivo = decide(evidence, parser.html_lang)
    return {"valenciano": valenciano, "motivo": motivo, "html_lang": parser.html_lang,
            **{key: sorted(vals)[:10] for key, vals in evidence.items()},
            "alternates": alternates,
            "translate_widget": bool(TRANSLATE_WIDGET.search(body))}


def main(html_dir, dst):
    index = json.load(open(os.path.join(html_dir, "index.json"), encoding="utf-8"))
    out = []
    for entry in index:
        with open(os.path.join(html_dir, f"{entry['idx']}.html"), encoding="utf-8") as fh:
            body = fh.read()
        out.append({**entry, **analyse(body, entry["final"] or entry["url"])})
    with open(dst, "w", encoding="utf-8") as fh:
        json.dump(out, fh, ensure_ascii=False, indent=1)
    has_val = sum(1 for o in out if o.get("val"))
    only_other = sum(1 for o in out if not o.get("val") and o.get("other"))
    print(f"total={len(out)} con_val={has_val} solo_otros={only_other} "
          f"sin_selector={len(out) - has_val - only_other}")


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])

