def decide(evidence, html_lang):
    """true: hay opción de valenciano; false: hay selector sin valenciano; null: no hay selector."""
    if evidence["val"]:
        labels = [ev.split("|")[0] for ev in evidence["val"]]
        if all(re.search(r"catal", label, re.I) for label in labels):
