"""Para portadas sin selector que son páginas de entrada, sigue el enlace a la web municipal y la analiza.

Uso: python3 -I follow_landing.py <lang.json> <render.json> <dir_render> <dir_html> <dir_salida> <salida.json>
"""
import json
import os
import re
import sys
from concurrent.futures import ThreadPoolExecutor
from html.parser import HTMLParser
from urllib.parse import urljoin, urlparse

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from render_pages import WORKERS, render  # noqa: E402

WEB_MUNICIPAL_TEXT = re.compile(r"web municipal|portal municipal", re.I)
GATEWAY_TEXT = re.compile(r"^(ajuntament|ayuntamiento)$", re.I)
PORTADA_PATH = re.compile(r"^/((ca|va|es)/)?portada/?$", re.I)


class LinkParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.links, self.current = [], None

    def handle_starttag(self, tag, attrs):
        if tag == "a":
            self.current = [dict(attrs).get("href") or "", ""]

    def handle_data(self, data):
        if self.current is not None:
            self.current[1] += data

    def handle_endtag(self, tag):
        if tag == "a" and self.current is not None:
            self.links.append((self.current[0], re.sub(r"\s+", " ", self.current[1]).strip()))
            self.current = None


def landing_target(dom, page_url):
    """URL de la web municipal enlazada desde una página de entrada, o None."""
    parser = LinkParser()
    parser.feed(dom)
    host = (urlparse(page_url).hostname or "").removeprefix("www.")
    for href, text in parser.links:
        url = urljoin(page_url, href)
        target = urlparse(url)
        target_host = (target.hostname or "").removeprefix("www.")
        if not (target_host == host or target_host.endswith("." + host)):
            continue
        if url.rstrip("/") == page_url.rstrip("/"):
            continue
        is_subdomain_gateway = target_host != host and GATEWAY_TEXT.match(text)
        if PORTADA_PATH.match(target.path) or WEB_MUNICIPAL_TEXT.search(text) or is_subdomain_gateway:
            return url
    return None


def main(static_path, render_path, render_dir, html_dir, out_dir, dst):
    static = {e["idx"]: e for e in json.load(open(static_path, encoding="utf-8"))}
    rendered = {e["idx"]: e for e in json.load(open(render_path, encoding="utf-8"))}
    jobs = []
    for idx, entry in static.items():
        final = rendered[idx]["r_valenciano"] if idx in rendered else entry["valenciano"]
        if final != "null" or entry["code"] == 503:
            continue
        source_dir = render_dir if idx in rendered else html_dir
        with open(os.path.join(source_dir, f"{idx}.html"), encoding="utf-8") as fh:
            target = landing_target(fh.read(), entry["final"] or entry["url"])
        if target:
            jobs.append(({"idx": f"{idx}_web", "url": target, "final": target, "landing_of": idx}, out_dir))
    os.makedirs(out_dir, exist_ok=True)
    with ThreadPoolExecutor(WORKERS) as pool:
        results = list(pool.map(render, jobs))
    with open(dst, "w", encoding="utf-8") as fh:
        json.dump(results, fh, ensure_ascii=False, indent=1)
    for r in results:
        print(r["landing_of"], r["url"][:60], r["rendered_len"], r["r_valenciano"], (r["r_val"] or r["r_other"])[:2])


if __name__ == "__main__":
    main(*sys.argv[1:7])

