"""Añade la columna 'valenciano' al CSV combinando todos los análisis.

Uso: python3 -I add_valenciano.py <csv> <lang.json> <render.json> <landing.json> <fixes.json>
                                  <csv_salida> <informe_csv>
Prioridad: web corregida (fixes) > web municipal enlazada desde la entrada (landing) >
portada renderizada con JS > HTML estático. Solo se rellena en filas con comprobado=true.
"""
import csv
import json
import sys

DOWN_CODES = {0, 503}


def load_by_idx(path, key="idx"):
    return {int(str(e[key]).split("_")[0]): e for e in json.load(open(path, encoding="utf-8"))}


def from_render(entry, suffix):
    ev = entry.get("r_val") or entry.get("r_other") or []
    return entry["r_valenciano"], entry["r_motivo"] + suffix, ev, entry.get("r_html_lang", "")


def merge(static, rendered, landing, fix):
    """Resultado final (valor, motivo, evidencia, lang de la página) de una web."""
    if fix:
        return from_render(fix, " (web corregida)")
    if landing and landing.get("r_valenciano") in ("true", "false"):
        return from_render(landing, f" (en {landing['url']}, enlazada desde la portada)")
    if rendered and rendered.get("r_valenciano") in ("true", "false"):
        return from_render(rendered, " (tras ejecutar JS)")
    lang = static.get("html_lang", "")
    if static.get("valenciano") in ("true", "false"):
        ev = static.get("val") or static.get("other") or []
        return static["valenciano"], static["motivo"], ev, lang
    if static["code"] in DOWN_CODES:
        return "null", f"web no accesible al comprobar (HTTP {static['code']})", [], ""
    return "null", "no se encuentra selector de idioma", [], lang


def main(src, static_path, render_path, landing_path, fixes_path, dst, report_path):
    with open(src, encoding="utf-8-sig", newline="") as fh:
        reader = csv.DictReader(fh, delimiter=";")
        fields, rows = reader.fieldnames, list(reader)
    static = load_by_idx(static_path)
    rendered = load_by_idx(render_path)
    landing = load_by_idx(landing_path, key="landing_of")
    fixes = load_by_idx(fixes_path)
    out_rows, report = [], []
    for idx, row in enumerate(rows):
        if row["comprobado"] != "true":
            out_rows.append({**row, "valenciano": ""})
            continue
        value, motivo, evidence, lang = merge(static[idx], rendered.get(idx), landing.get(idx), fixes.get(idx))
        out_rows.append({**row, "valenciano": value})
        report.append({"Provincia": row["Provincia"], "Municipio": row["Municipio"], "web": row["web"],
                       "valenciano": value, "motivo": motivo, "lang_pagina": lang,
                       "evidencia": " || ".join(e.split("|")[0] for e in evidence[:3])})

