    if short:
        cases.append(("muy poco texto", "; ".join(f"{k}: {name_visits[k].get('textChars')} car." for k in short)))
    if any(name_visits[k].get("textFromFrames") for k in KEYS):
        cases.append(("texto leído de un iframe", ""))

