import csv,json,re,sys,collections
rows=list(csv.DictReader(open(sys.argv[1],encoding="utf-8-sig",newline=""),delimiter=";"))
L={}
for l in open(sys.argv[2]):
  v=json.loads(l); L[(v["row"],v["key"])]=v
print("=== paginas con detectores en desacuerdo: tramo central del texto")
for n in (153,157,430,290,95,138,512):
  v=L[(n,"es")]; t=" ".join(v["text"].split()); m=len(t)//2
  print(n,v["municipio"],v["textChars"],"|",t[m:m+230]); print()
print("=== efecto plataforma: prefijo del titulo")
def pref(t):
  t=t or ""
  if t.startswith("Inicio | Ayuntamiento"): return "Inicio | Ayuntamiento (Dip. Castelló)"
  if re.match(r"^(Landing|Portada) \|",t): return "Landing/Portada | (Dip. València)"
  return "otro"
tab=collections.Counter()
for i,r in enumerate(rows):
  v=L[(i+2,"es")]
  b=r["comportamiento_idioma"]; lab=("fijo "+r["es_idioma_texto"]) if b=="fijo" else b
  tab[(r["Provincia"],pref(v.get("title")),lab)]+=1
for k,c in sorted(tab.items()): print(" ",k,c)
print("=== etiquetas lang incorrectas (todas las visitas)")
W=("va","va-va","vl","val","x-va","es-va","ca-ca","zxx")
bad=collections.defaultdict(set)
for r in rows:
  for k in ("es","va","en"):
    if r[k+"_lang"].lower() in W: bad[r[k+"_lang"]].add(r["Municipio"])
for k,v in bad.items(): print(" ",k,len(v),sorted(v))
good=collections.Counter(r[k+"_lang"] for r in rows for k in ("es",) if r[k+"_lang"]); print(" todos:",good.most_common())
print("=== hreflang incorrecto")
hb=collections.defaultdict(set)
for r in rows:
  for k in ("es","va","en"):
    for t in r[k+"_hreflang"].split("|"):
      if t.lower() in W: hb[t].add(r["Municipio"])
for k,v in hb.items(): print(" ",k,len(v),sorted(v))
print("=== hreflang cambia entre visitas:",[r["Municipio"] for r in rows if len({r[k+"_hreflang"] for k in ("es","va","en") if r[k+"_url_final"]})>1])
print("=== con hreflang sin valenciano aunque hay boton:",[ (r["Municipio"],r["es_hreflang"]) for r in rows if r["es_hreflang"] and r["valenciano"]=="true" and not re.search(r"(^|\|)(ca|va|vl)",r["es_hreflang"].lower())])
print("=== hreflang con en y sitio:",sum(1 for r in rows if re.search(r"(^|\|)en",r["es_hreflang"])), "| en-US recibe ingles:",sum(1 for r in rows if r["en_idioma_texto"]=="en"), "| boton ingles (opcionesIdioma no disponible aqui)")
print("=== fijo con texto no identico entre visitas:",sum(1 for i,r in enumerate(rows) if r["comportamiento_idioma"]=="fijo" and len({L[(i+2,k)].get("textSha256") for k in ("es","va","en")})>1),"de",sum(1 for r in rows if r["comportamiento_idioma"]=="fijo"))
print("=== revisar misma pagina:",sum(1 for i,r in enumerate(rows) if r["comportamiento_idioma"]=="revisar" and len({L[(i+2,k)].get("textSha256") for k in ("es","va","en")})==1))
print("=== adaptativos: Vary / Content-Language / hreflang")
for i,r in enumerate(rows):
  if r["comportamiento_idioma"]=="adaptativo":
    print(" ",r["Municipio"][:24].ljust(24),"Vary=",L[(i+2,"es")].get("vary","")[:28].replace("\n",","),"| CL=",[L[(i+2,k)].get("contentLanguage") for k in ("es","va","en")],"| hreflang=",r["es_hreflang"],"| poblacion",r["Población"])
print("=== sin_datos:");
for i,r in enumerate(rows):
  if r["comportamiento_idioma"]=="sin_datos": print(" ",i+2,r["Municipio"],"pob",r["Población"],"comprobado",r["comprobado"],"|",L[(i+2,"es")].get("error","")[:80])
print("=== Benlloc:",[ (L[(230,k)].get("finalUrl"),L[(230,k)].get("textLanguage")) for k in ("es","va","en")], rows[228]["Municipio"])
' "$O" "$J" 2>&1 | cut -c1-330

